/**
 * Appends an existing contact or creates a contact if it doesn't exist.
 *
 * For internal docs, see
 * [Submit Contacts](crm.contact-submit-service.introduction).
 * @public
 * @documentationMaturity preview
 * @permissionId CONTACTS.SUBMIT
 * @applicableIdentity APP
 * @fqn com.wixpress.contacts.allocator.api.v4.ContactSubmitServiceV4.SubmitContact
 */
export async function appendOrCreateContact(
  options?: AppendOrCreateContactOptions
): Promise<
  NonNullablePaths<
    SubmitContactResponse,
    `contactId` | `identityType` | `newContact`,
    0
  > & {
    __applicationErrorsType?: AppendOrCreateContactApplicationErrors;
  }
> {
  // @ts-ignore
  const { httpClient, sideEffects } = arguments[1] as {
    httpClient: HttpClient;
    sideEffects?: any;
  };

  const payload = transformPaths(
    renameKeysFromSDKRequestToRESTRequest({
      info: options?.info,
      passThroughData: options?.passThroughData,
      contactId: options?.contactId,
    }),
    [
      {
        transformFn: transformSDKAddressToRESTAddress,
        paths: [{ path: 'info.addresses.items.address' }],
      },
      {
        transformFn: transformSDKImageToRESTImage,
        paths: [{ path: 'info.picture.image' }],
      },
    ]
  );

  const reqOpts = ambassadorWixContactsV4SubmitContact.submitContact(payload);

  sideEffects?.onSiteCall?.();
  try {
    const result = await httpClient.request(reqOpts);
    sideEffects?.onSuccess?.(result);

    return renameKeysFromRESTResponseToSDKResponse(result.data)!;
  } catch (err: any) {
    const transformedError = sdkTransformError(
      err,
      {
        spreadPathsToArguments: {},
        explicitPathsToArguments: {
          info: '$[0].info',
          passThroughData: '$[0].passThroughData',
          contactId: '$[0].contactId',
        },
        singleArgumentUnchanged: false,
      },
      ['options']
    );
    sideEffects?.onError?.(err);

    throw transformedError;
  }
}

export interface AppendOrCreateContactOptions {
  /**
   * Contact's information.
   * To reconcile with an existing contact,
   * a phone or email must be provided,
   * or the current session identity must be attached to a contact or member.
   *
   * If no existing contact can be found,
   * a new contact is created with the specified information.
   *
   * <!--ONLY:REST-->
   * Required if there's no contextual identity or given `contactId`.
   * <!--END:ONLY:REST-->
   */
  info?: ContactInfo;
  /**
   * Pass through data, to be posted on Contact Submitted Domain Event (optional).
   * @maxLength 300
   */
  passThroughData?: string | null;
  /**
   * Existing Contact ID (optional).
   * Requires permission `CONTACTS.SUBMIT_WITH_OVERRIDES`
   * @format GUID
   */
  contactId?: string | null;
}
